import sys

def is_composite(x: int) -> bool:
    if x < 4:
        return False
    if x % 2 == 0:
        return True
    if x % 3 == 0:
        return True
    i = 5
    while i * i <= x:
        if x % i == 0 or x % (i + 2) == 0:
            return True
        i += 6
    return False

