import sys

def lcs_length(a, b):
    n, m = len(a), len(b)
    dp = [0] * (m + 1)
    for i in range(1, n + 1):
        prev = 0
        for j in range(1, m + 1):
            cur = dp[j]
            if a[i - 1] == b[j - 1]:
                dp[j] = prev + 1
            else:
                dp[j] = dp[j] if dp[j] > dp[j - 1] else dp[j - 1]
            prev = cur
    return dp[m]

def main():
    data = sys.stdin.read().splitlines()
    if len(data) >= 2:
        a = data[0].rstrip('\n')
        b = data[1].rstrip('\n')
        print(lcs_length(a, b))

