import sys, math

def factorize(n):
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        factors.append(n)
    return factors

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    q = int(data[0])
    if q == 1:
        print(1)
        print(0)
        return
    facs = factorize(q)
    cnt = len(facs)
    if cnt == 1:
        # prime
        print(1)
        print(0)
    elif cnt == 2:
        print(2)
    else:
        # first wins, need a losing divisor (with exactly two prime factors)
        d = facs[0] * facs[1]
        print(1)
        print(d)

if __name__ == "__main__":
    main()

