cc_p01624 Ononokomachi's Edit War.code:
import sys

ALLOWED = set("0123456789()*+-&^|")

def is_valid(expr: str) -> bool:
    if not expr:
        return False
    if any(c not in ALLOWED for c in expr):
        return False
    try:
        eval(expr, {"__builtins__": None}, {})
        return True
    except Exception:
        return False

def eval_expr(expr: str) -> int:
    return eval(expr, {"__builtins__": None}, {})

def successors(s: str):
    res = set()
    L = len(s)
    # deletions
    for i in range(L):
        t = s[:i] + s[i+1:]
        if is_valid(t):
            res.add(t)
    # insertions
    chars = list(ALLOWED)
    for i in range(L+1):
        for c in chars:
            t = s[:i] + c + s[i:]
            if is_valid(t):
                res.add(t)
    return list(res)

from functools import lru_cache

def solve_dataset(N, expr):
    @lru_cache(maxsize=None)
    def dfs(state, moves_left, player):
        if moves_left == 0:
            return eval_expr(state)
        succ = successors(state)
        if not succ:
            # no valid moves, stay same
            return eval_expr(state)
        if player == 0:  # max
            best = -10**30
            for ns in succ:
                val = dfs(ns, moves_left-1, 1)
                if val > best:
                    best = val
            return best
        else:  # min
            best = 10**30
            for ns in succ:
                val = dfs(ns, moves_left-1, 0)
                if val < best:
                    best = val
            return best
    return dfs(expr, N, 0)

def main():
    out = []
    for line in sys.stdin:
        line=line.rstrip('\n')
        if not line:
            continue
        if line.startswith('0'):
            break
        parts=line.split()
        N=int(parts[0])
        expr=''.join(parts[1:]).replace(' ','')
