cc_p00776 Encryption System.code:
import sys

def encrypt(s):
    s = list(s)
    for c in range(ord('b'), ord('z')+1):
        prev = chr(c-1)
        curr = chr(c)
        for i in range(len(s)):
            if s[i] == curr:
                s[i] = prev
                break
    return ''.join(s)

def get_candidates(encrypted):
    target = encrypted

    def reverse_encrypt(s):
        states = {s}
        for c_ord in range(ord('z'), ord('a'), -1):
            c = chr(c_ord)
            prev = chr(c_ord - 1)
            new_states = set()
            for state in states:
                # Option 1: no change (the forward step either didn't find c, or first prev was truly prev)
                new_states.add(state)

                # Find first occurrence of c in state (existing c's)
                first_c = state.find(c)

                # Can change any prev that appears before first_c (or all if no c exists)
                for idx in range(len(state)):
                    if state[idx] == prev:
                        if first_c == -1 or idx < first_c:
                            new_state = state[:idx] + c + state[idx+1:]
                            new_states.add(new_state)
                        else:
                            break
            states = new_states
        return states

    candidates = reverse_encrypt(target)

    verified = []
    for cand in candidates:
        if encrypt(cand) == target:
            verified.append(cand)

    verified.sort()
    return verified

for line in sys.stdin:
    line = line.rstrip('\n')
    if line == '#':
        break
    encrypted = line
    candidates = get_candidates(encrypted)
    n = len(candidates)
    print(n)
    if n <= 10:
        for c in candidates:
            print(c)
    else:
        for c in candidates[:5]:
            print(c)
        for c in candidates[-5:]:
            print(c)

