    idx = 0
    INF = float('inf')
    out = []
    while True:
        n = int(input_data[idx]); m = int(input_data[idx+1]); idx += 2
        if n == 0 and m == 0:
            break
        # adjacency for land and combined
        land = [[INF]*(n+1) for _ in range(n+1)]
        comb = [[INF]*(n+1) for _ in range(n+1)]
        for i in range(1, n+1):
            land[i][i] = 0
            comb[i][i] = 0
        land_edges = []
        comb_edges = []
        for _ in range(m):
            a = int(input_data[idx]); b = int(input_data[idx+1])
            c = int(input_data[idx+2]); typ = input_data[idx+3]; idx += 4
            if typ == 'L':
                if c < land[a][b]:
                    land[a][b] = c
                    land[b][a] = c
            if c < comb[a][b]:
                comb[a][b] = c
                comb[b][a] = c

        # Floyd-Warshall for land
        for k in range(1, n+1):
            lk = land[k]
            for i in range(1, n+1):
                lik = land[i][k]
                if lik == INF:
                    continue
                li = land[i]
                for j in range(1, n+1):
                    v = lik + lk[j]
                    if v < li[j]:
                        li[j] = v
        # Floyd-Warshall for combined
        for k in range(1, n+1):
            ck = comb[k]
            for i in range(1, n+1):
                cik = comb[i][k]
                if cik == INF:
                    continue
                ci = comb[i]
                for j in range(1, n+1):
                    v = cik + ck[j]
                    if v < ci[j]:
                        ci[j] = v

        R = int(input_data[idx]); idx += 1
        seq = [int(input_data[idx+i]) for i in range(R)]
        idx += R

        # DP: dp[s] = min cost to reach current town with ship at town s
        start = seq[0]
        dp = [INF]*(n+1)
        # initially ship position unknown - ship starts wherever; we say ship at start (Toto's start)
        # Actually the ship can start at any port; but standard interpretation: ship starts at seq[0].
        dp[start] = 0

        for step in range(1, R):
            prev = seq[step-1]
            cur = seq[step]
            ndp = [INF]*(n+1)
            # Land only: ship stays at s
            for s in range(1, n+1):
                if dp[s] == INF:
                    continue
                base = dp[s]
                if land[prev][cur] != INF:
                    val = base + land[prev][cur]
                    if val < ndp[s]:
                        ndp[s] = val
            # Use ship
            for s in range(1, n+1):
                if dp[s] == INF:
                    continue
                base = dp[s]
                # walk to ship at s
                if land[prev][s] == INF:
                    continue
                cost1 = base + land[prev][s]
                # sail in combined graph from s to q, ship ends at q
                cs = comb[s]
                for q in range(1, n+1):
                    if cs[q] == INF:
                        continue
                    if land[q][cur] == INF:
                        continue
                    val = cost1 + cs[q] + land[q][cur]
                    if val < ndp[q]:
                        ndp[q] = val
            dp = ndp

        ans = min(dp[1:])
        if ans == INF:
            out.append("inf")
        else:
            out.append(str(ans))

    print('\n'.join(out))

