import sys

def solve():
    it = iter(sys.stdin.read().splitlines())
    out_lines = []
    for line in it:
        if not line:
            continue
        h, w = map(int, line.split())
        if h == 0 and w == 0:
            break
        grid = [list(next(it).rstrip()) for _ in range(h)]

        dp = [[None] * w for _ in range(h)]

        def add_state(cell_dict, stack, cnt):
            prev = cell_dict.get(stack)
            if prev is None or cnt > prev:
                cell_dict[stack] = cnt

        # start
        start_dict = {}
        start_char = grid[0][0]
        # option: do nothing
        add_state(start_dict, (), 0)
        # if jewel
        if 'a' <= start_char <= 'z':
            add_state(start_dict, (start_char,), 0)
        # if hole (cannot place because stack empty)
        dp[0][0] = start_dict

        for i in range(h):
            for j in range(w):
                if i == 0 and j == 0:
                    continue
                if grid[i][j] == '#':
                    dp[i][j] = None
                    continue
                cur = {}
                sources = []
                if i > 0 and dp[i-1][j]:
                    sources.append(dp[i-1][j])
                if j > 0 and dp[i][j-1]:
                    sources.append(dp[i][j-1])
                for src in sources:
                    for stack, cnt in src.items():
                        # do nothing
                        add_state(cur, stack, cnt)
                        ch = grid[i][j]
                        if 'a' <= ch <= 'z':
                            # pick jewel
                            add_state(cur, stack + (ch,), cnt)
                        elif 'A' <= ch <= 'Z':
                            # place if top matches
                            if stack and stack[-1] == ch.lower():
                                add_state(cur, stack[:-1], cnt + 1)
                dp[i][j] = cur if cur else None

        end_dict = dp[h-1][w-1]
        if not end_dict:
            out_lines.append("-1")
        else:
            out_lines.append(str(max(end_dict.values())))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

