    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1

    D = []
    for i in range(N):
        D.append(int(data[idx])); idx += 1

    C = []
    for j in range(M):
        C.append(int(data[idx])); idx += 1

    # dp[i][j] = minimum fatigue to reach city i by end of day j
    # i ranges 0..N, j ranges 0..M
    INF = float('inf')

    dp = [[INF] * (M + 1) for _ in range(N + 1)]
    dp[0][0] = 0

    for j in range(M + 1):
        for i in range(N + 1):
            if dp[i][j] == INF:
                continue
            # Wait: stay at city i, move to day j+1
            if j + 1 <= M:
                if dp[i][j + 1] > dp[i][j]:
                    dp[i][j + 1] = dp[i][j]
            # Move: move to city i+1 on day j+1
            if i + 1 <= N and j + 1 <= M:
                cost = dp[i][j] + D[i] * C[j]  # moving on day j+1, which is C[j] (0-indexed)
                if dp[i + 1][j + 1] > cost:
                    dp[i + 1][j + 1] = cost

    ans = min(dp[N][j] for j in range(N, M + 1))
    print(ans)

