import sys

def solve():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    out_lines = []
    while True:
        try:
            T = int(next(it))
        except StopIteration:
            break
        if T == 0:
            break
        t = [0] + [int(next(it)) for _ in range(T)]
        N = int(next(it))
        max_day = 0
        limit = [23] * 101  # days 1..100
        for _ in range(N):
            d = int(next(it)); m = int(next(it))
            if m < limit[d]:
                limit[d] = m
            if d > max_day:
                max_day = d
        # DP arrays
        INF = 10**9
        dp_prev = [INF] * (T + 1)
        # day 1 must be index 1
        if t[1] <= limit[1]:
            dp_prev[1] = 0
        else:
            # impossible, but per constraints shouldn't happen
            out_lines.append(str(-1))
            continue
        for day in range(2, max_day + 1):
            dp_cur = [INF] * (T + 1)
            for prev_idx in range(1, T + 1):
                cost = dp_prev[prev_idx]
                if cost >= INF:
                    continue
                # no reset
                cur_idx = prev_idx % T + 1
                if t[cur_idx] <= limit[day]:
                    if cost < dp_cur[cur_idx]:
                        dp_cur[cur_idx] = cost
                # reset
                if t[1] <= limit[day]:
                    if cost + 1 < dp_cur[1]:
                        dp_cur[1] = cost + 1
            dp_prev = dp_cur
        ans = min(dp_prev[1:])  # ignore index 0
        out_lines.append(str(ans))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

