import sys

def get_interval(poly, x):
    vals = []
    n = len(poly)
    for i in range(n):
        a = poly[i]
        b = poly[(i+1)%n]
        if abs(b[0]-a[0]) < 1e-12:
            if abs(a[0]-x) < 1e-9:
                vals.append(a[1])
                vals.append(b[1])
        else:
            t = (x - a[0]) / (b[0] - a[0])
            if -1e-9 <= t <= 1+1e-9:
                y = a[1] + t*(b[1]-a[1])
                vals.append(y)
    if len(vals) < 2:
        xs = [p[0] for p in poly]
        if x < min(xs)-1e-9 or x > max(xs)+1e-9:
            return None
        if not vals:
            return None
        return (vals[0], vals[0])
    return (min(vals), max(vals))

def cross_section_area_at_x(poly1_xy, poly2_xz, x):
    iv1 = get_interval(poly1_xy, x)
    iv2 = get_interval(poly2_xz, x)
    if iv1 is None or iv2 is None:
        return 0.0
    y_len = max(0.0, iv1[1] - iv1[0])
    z_len = max(0.0, iv2[1] - iv2[0])
    return y_len * z_len

def get_x_range(poly):
    xs = [p[0] for p in poly]
    return min(xs), max(xs)

def solve(poly1, poly2):
    x1_min, x1_max = get_x_range(poly1)
    x2_min, x2_max = get_x_range(poly2)
    x_min = max(x1_min, x2_min)
    x_max = min(x1_max, x2_max)
    if x_min >= x_max - 1e-12:
        return 0.0

    xs = set()
    for p in poly1:
        xs.add(p[0])
    for p in poly2:
        xs.add(p[0])
    xs = sorted(x for x in xs if x_min - 1e-9 <= x <= x_max + 1e-9)
    xs = [max(x_min, min(x_max, x)) for x in xs]
    xs = sorted(set([x_min, x_max] + xs))

    volume = 0.0
    for i in range(len(xs)-1):
        a = xs[i]
        b = xs[i+1]
        if b - a < 1e-12:
            continue
        fa = cross_section_area_at_x(poly1, poly2, a)
        fm = cross_section_area_at_x(poly1, poly2, (a+b)/2)
        fb = cross_section_area_at_x(poly1, poly2, b)
        volume += (b-a)/6.0 * (fa + 4*fm + fb)
    return volume

def main():
    data = sys.stdin.read().split()
    idx = 0
    while idx < len(data):
        m = int(data[idx]); n = int(data[idx+1]); idx += 2
        if m == 0 and n == 0:
            break
        poly1 = []
        for _ in range(m):
            x = float(data[idx]); y = float(data[idx+1]); idx += 2
            poly1.append((x,y))
        poly2 = []
        for _ in range(n):
            x = float(data[idx]); z = float(data[idx+1]); idx += 2
            poly2.append((x,z))
        vol = solve(poly1, poly2)
        print("%.16f" % vol)

main()

