import sys

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    p = [0] + [int(next(it)) for _ in range(n)]
    pos = [0] * (n + 1)
    for i in range(1, n + 1):
        pos[p[i]] = i

    swaps = []

    def do_swap(a: int, b: int) -> None:
        if a == b:
            return
        assert 2 * abs(a - b) >= n
        swaps.append((a, b))
        p[a], p[b] = p[b], p[a]
        pos[p[a]] = a
        pos[p[b]] = b

    half = n // 2

    def smart_swap(i: int, j: int) -> None:
        if i == j:
            return
        if 2 * abs(i - j) >= n:
            do_swap(i, j)
            return
        if i > j:
            i, j = j, i
        # i < j, too close
        if j <= half:
            pivot = n
            do_swap(i, pivot); do_swap(j, pivot); do_swap(i, pivot)
        elif i > half:
            pivot = 1
            do_swap(i, pivot); do_swap(j, pivot); do_swap(i, pivot)
        else:
            # i <= half, j > half, too close
            do_swap(i, n); do_swap(1, j); do_swap(1, n); do_swap(i, n); do_swap(1, j)

    for v in range(1, n + 1):
        while pos[v] != v:
            smart_swap(v, pos[v])

    out = [str(len(swaps))]
    out += [f"{a} {b}" for a, b in swaps]
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

