cc_p00837 Book Replacement.code:
import sys
from collections import deque

def simulate(m, c, students_requests):
    # Desks: list of lists (D1 to Dm), shelf is implicit
    # Each desk can hold up to c books
    # We need to track order of books on each desk (for LRU on D1)

    # desks[i] = list of book IDs on desk i+1 (0-indexed)
    # For D1 (desks[0]), we need LRU ordering
    # We'll represent each desk as an ordered list where books are in order of use
    # For D1, leftmost = least recently used, rightmost = most recently used
    # For other desks, order doesn't matter for LRU, but we still track them

    desks = [[] for _ in range(m)]
    # shelf holds books not on any desk
    shelf = set()

    total_cost = 0

    # Build queue of (student_index, request_index)
    queue = deque()
    for i, reqs in enumerate(students_requests):
        if reqs:
            queue.append((i, 0))

    def find_book(book_id):
        # Returns ('desk', desk_index) or ('shelf', None)
        for i in range(m):
            if book_id in desks[i]:
                return ('desk', i)
        return ('shelf', None)

    def find_space_closest_to_entrance(exclude_desk=None):
        # Returns index of non-full desk closest to entrance (excluding exclude_desk)
        # or 'shelf' if all desks are full
        for i in range(m):
            if exclude_desk is not None and i == exclude_desk:
                continue
            if len(desks[i]) < c:
                return ('desk', i)
        return ('shelf', None)

    def access_cost(location):
        if location[0] == 'desk':
            return location[1] + 1  # desk index is 0-based, cost is i+1
        else:
            return m + 1

    while queue:
        student_idx, req_idx = queue.popleft()
        book_id = students_requests[student_idx][req_idx]

        # Find the book
        book_loc = find_book(book_id)

        # Cost of taking the book (finding it)
        # Taking from desk or shelf costs access_cost
        take_cost = access_cost(book_loc)
        total_cost += take_cost

        # Remove book from current location
        if book_loc[0] == 'desk':
            desks[book_loc[1]].remove(book_id)
        else:
            shelf.discard(book_id)

        # Now put book on D1
        if len(desks[0]) < c:
            # D1 not full, just put it there
            desks[0].append(book_id)
            total_cost += 1  # cost of putting on D1
        else:
            # D1 is full
            # Step 1: temporarily put requested book on non-full desk closest to entrance
            # or shelf if all full
            temp_loc = find_space_closest_to_entrance(exclude_desk=None)
            total_cost += access_cost(temp_loc)
            if temp_loc[0] == 'desk':
                desks[temp_loc[1]].append(book_id)
            else:
                shelf.add(book_id)

            # Step 2: find LRU book on D1 (least recently used = first in list)
            lru_book = desks[0][0]
            desks[0].pop(0)
            total_cost += 1  # cost of taking from D1

            # Step 3: put LRU book on non-full desk (except D1) closest to entrance
            # or shelf if all desks except D1 are full
            dest_loc = find_space_closest_to_entrance(exclude_desk=0)
            total_cost += access_cost(dest_loc)
            if dest_loc[0] == 'desk':
                desks[dest_loc[1]].append(lru_book)
            else:
                shelf.add(lru_book)

            # Step 4: take requested book from temp place
            if temp_loc[0] == 'desk':
                desks[temp_loc[1]].remove(book_id)
            else:
                shelf.discard(book_id)
            total_cost += access_cost(temp_loc)

            # Step 5: put requested book on D1
            desks[0].append(book_id)
            total_cost += 1

        # Enqueue next request for this student
        if req_idx + 1 < len(students_requests[student_idx]):
            queue.append((student_idx, req_idx + 1))

    return total_cost

for line in sys.stdin:
    parts = line.split()
    m, c, n = int(parts[0]), int(parts[1]), int(parts[2])
    if m == 0 and c == 0 and n == 0:
        break

    students_requests = []
    for i in range(n):
        k = int(input())
        books = list(map(int, input().split()))
        students_requests.append(books)

    print(simulate(m, c, students_requests))

