import sys

def is_sorted(arr):
    n = len(arr)
    inc = True
    dec = True
    for i in range(1, n):
        if arr[i] < arr[i-1]:
            inc = False
        if arr[i] > arr[i-1]:
            dec = False
        if not inc and not dec:
            return False
    return True

def try_swap(a, i, j):
    if a[i] == a[j]:
        return False
    a[i], a[j] = a[j], a[i]
    ok = not is_sorted(a)
    a[i], a[j] = a[j], a[i]
    return ok

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    if n < 2:
        print(-1)
        return

    candidates = set()
    boundary = min(n, 6)
    for i in range(boundary):
        for j in range(i+1, n):
            if a[i] != a[j]:
                candidates.add((i, j))
    for i in range(n - boundary, n):
        for j in range(i+1, n):
            if a[i] != a[j]:
                candidates.add((i, j))
    for i in range(max(0, n-6), n):
        for j in range(i+1, n):
            if a[i] != a[j]:
                candidates.add((i, j))
    # Add all adjacent pairs
    for i in range(n-1):
        if a[i] != a[i+1]:
            candidates.add((i, i+1))
    # Add pairs near each inequality "violation" boundary
    for i in range(1, n):
        # window around i
        lo = max(0, i-2)
        hi = min(n, i+2)
        for x in range(lo, hi):
            for y in range(x+1, hi):
                if a[x] != a[y]:
                    candidates.add((x, y))

    for i, j in candidates:
        if try_swap(a, i, j):
            print(i+1, j+1)
            return

    print(-1)

