import sys

def main():
    data = sys.stdin.read().strip().split()
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    max_val = max(a)
    min_val = min(a)
    max_diff = max_val - min_val
    shift = max_diff

    freqA = [0] * (2 * max_diff + 1)
    freqB = [0] * (2 * max_diff + 1)

    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            d = a[j] - a[i]
            idx = d + shift
            if d < 0:
                freqA[idx] += 1
            elif d > 0:
                freqB[idx] += 1

    m = sum(freqA)
    k = sum(freqB)

    size = 2 * max_diff + 1
    # Convolve freqA with freqA using DP
    conv = [0] * (2 * size - 1)
    for i in range(size):
        if freqA[i] == 0:
            continue
        for j in range(size):
            if freqA[j] == 0:
                continue
            conv[i + j] += freqA[i] * freqA[j]

    total_fav = 0
    for idx_s, cnt in enumerate(conv):
        if cnt == 0:
            continue
        s = idx_s - 2 * shift
        # need d3 > -s  (strictly), index > -s + shift
        start = -s + shift + 1
        if start < 0:
            start = 0
        if start >= size:
            continue
        sumB = sum(freqB[start:])
        total_fav += cnt * sumB

    prob = total_fav / (m * m * k)
    print("{:.10f}".format(prob))

