    n = len(tokens) - 1
    delta = Fraction(90, 2 ** n)
    return suffix_angle - delta if tokens[0] == 'north' else suffix_angle + delta

def split_tokens(s):
    tokens = []
    i = 0
    while i < len(s):
        if s.startswith('north', i):
            tokens.append('north')
            i += 5
        else:
            tokens.append('west')
            i += 4
    return tokens

out_lines = []
for line in sys.stdin:
    line = line.strip()
    if line == '#':
        break
    tokens = split_tokens(line)
    angle = compute_angle(tokens)
    if angle.denominator == 1:
        out_lines.append(str(angle.numerator))
    else:
        out_lines.append(f"{angle.numerator}/{angle.denominator}")

sys.stdout.write("\n".join(out_lines))

