import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, k = map(int, data)
    if k > 26 or k > n or (k == 1 and n > 1):
        print("-1")
        return
    result = []
    used = set()
    for i in range(n):
        for c in (chr(ord('a') + j) for j in range(26)):
            if i > 0 and result[-1] == c:
                continue
            new_used = used | {c}
            remaining = n - i - 1
            need = k - len(new_used)
            if need < 0:
                continue
            if remaining < need:
                continue
            # feasible
            result.append(c)
            used.add(c)
            break
        else:
            print("-1")
            return
    if len(used) != k:
        print("-1")
    else:
        print(''.join(result))

if __name__ == "__main__":
    solve()

cc_39_E. What Has Dirichlet Got to Do wi.code:
import sys
from functools import lru_cache

def main():
    data = sys.stdin.read().strip().split()
    a, b, n = map(int, data)

    WIN, LOSE, DRAW = 1, 0, 2

    def ways_ge(a, b, n):
        # check if a^b >= n
        result = 1
        for _ in range(b):
            result *= a
            if result >= n:
                return True
        return False

    sys.setrecursionlimit(1000000)

    @lru_cache(maxsize=None)
    def solve(a, b):
        outcomes = []

        # box move
        if ways_ge(a + 1, b, n):
            outcomes.append(LOSE)  # current loses by making this move
        else:
            opp = solve(a + 1, b)
            if opp == LOSE:
                outcomes.append(WIN)
            elif opp == WIN:
                outcomes.append(LOSE)
            else:
                outcomes.append(DRAW)

        # item move
        if a == 1:
            # 1^anything = 1 < n always; can keep adding items forever -> draw
            outcomes.append(DRAW)
        else:
            if ways_ge(a, b + 1, n):
                outcomes.append(LOSE)
            else:
                opp = solve(a, b + 1)
                if opp == LOSE:
                    outcomes.append(WIN)
                elif opp == WIN:
                    outcomes.append(LOSE)
                else:
                    outcomes.append(DRAW)

        if WIN in outcomes:
            return WIN
        if DRAW in outcomes:
            return DRAW
        return LOSE

    result = solve(a, b)
    if result == WIN:
        print("Masha")  # Stas wins (current player wins -> Masha is the answer per spec)
    elif result == LOSE:
        print("Stas")
    else:
        print("Missing")

if __name__ == "__main__":
    main()

cc_172_D. Calendar Reform.code:
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    a, n = map(int, data)
    max_val = a + n - 1
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:
            step = i
            start = i * i
            for j in range(start, max_val + 1, step):
                if spf[j] == j:
                    spf[j] = i
    total = 0
    for L in range(a, a + n):
        x = L
        sq = 1
        while x > 1:
            p = spf[x]
            cnt = 0
            while x % p == 0:
                x //= p
                cnt += 1
            exp = cnt - (cnt & 1)  # largest even <= cnt
            if exp:
                sq *= p ** exp
        total += L // sq
    sys.stdout.write(str(total))

if __name__ == "__main__":
    solve()

cc_p00874 Cubist Artwork.code:
import sys

def solve():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    out_lines = []
    for w_str in it:
        w = int(w_str)
        d = int(next(it))
        if w == 0 and d == 0:
            break
        front = [int(next(it)) for _ in range(w)]
        side = [int(next(it)) for _ in range(d)]

        # DP over columns, mask of used rows
        from functools import lru_cache

        @lru_cache(None)
        def dp(col, mask):
            if col == w:
                return 0
            best = dp(col + 1, mask)  # skip matching this column
            for r in range(d):
                if not (mask >> r) & 1 and front[col] == side[r]:
                    cand = front[col] + dp(col + 1, mask | (1 << r))
                    if cand > best:
                        best = cand
            return best

        max_save = dp(0, 0)
        total = sum(front) + sum(side) - max_save
        out_lines.append(str(total))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

