import sys

def solve():
    data = sys.stdin.read().split()
    it = iter(data)
    out_lines = []
    while True:
        try:
            N = int(next(it))
            M = int(next(it))
        except StopIteration:
            break
        if N == 0 and M == 0:
            break

        questions = []
        for _ in range(M):
            Si = int(next(it))
            ki = int(next(it))
            eligible = set()
            for _ in range(ki):
                c = int(next(it))
                eligible.add(c)
            questions.append((Si, eligible))

        # For each pair (p, q), compute max(score_q - score_p)
        # S_{M+1} = max over all pairs + 1

        max_diff = 0
        for p in range(1, N+1):
            for q in range(1, N+1):
                if p == q:
                    continue
                diff = 0
                for Si, eligible in questions:
                    if q in eligible:
                        diff += Si
                    elif p in eligible:
                        diff -= Si
                if diff > max_diff:
                    max_diff = diff

        out_lines.append(str(max_diff + 1))

    print("\n".join(out_lines))

if __name__ == "__main__":
    solve()
